class Solution {
public:
    int countSubarrays(vector<int>& nums, int a, int b) {
        vector<long long> f{0};
        long long e = 0, o = 0;
        for (int x : nums) {
            if (x % 2 == 0) e++; else o++;
            f.push_back(b * e - a * o);
        }
        int n = f.size(), ans = 0;
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                if (f[i] <= f[j]) ans++;
        return ans;
    }
};

