class Solution:
    def countSubarrays(self, nums, a, b):
        e = o = 0
        f = [0]
        for x in nums:
            if x % 2 == 0: e += 1
            else: o += 1
            f.append(b * e - a * o)
        def solve(v):
            if len(v) <= 1: return v, 0
            m = len(v) // 2
            lo, c1 = solve(v[:m])
            hi, c2 = solve(v[m:])
            cnt, res, i, j = c1 + c2, [], 0, 0
            while i < len(lo) and j < len(hi):
                if lo[i] <= hi[j]:
                    cnt += len(hi) - j
                    res.append(lo[i]); i += 1
                else:
                    res.append(hi[j]); j += 1
            res.extend(lo[i:]); res.extend(hi[j:])
            return res, cnt
        return solve(f)[1]

