class Solution {
    long long solve(vector<long long>& v, vector<long long>& buf, int l, int r) {
        if (r - l <= 1) return 0;
        int m = (l + r) / 2;
        long long cnt = solve(v, buf, l, m) + solve(v, buf, m, r);
        int i = l, j = m, k = l;
        while (i < m && j < r) {
            if (v[i] <= v[j]) { cnt += r - j; buf[k++] = v[i++]; }
            else buf[k++] = v[j++];
        }
        while (i < m) buf[k++] = v[i++];
        while (j < r) buf[k++] = v[j++];
        for (int t = l; t < r; t++) v[t] = buf[t];
        return cnt;
    }
public:
    int countSubarrays(vector<int>& nums, int a, int b) {
        vector<long long> f{0};
        long long e = 0, o = 0;
        for (int x : nums) {
            if (x % 2 == 0) e++; else o++;
            f.push_back(b * e - a * o);
        }
        vector<long long> buf(f.size());
        return (int)solve(f, buf, 0, f.size());
    }
};

