class Solution {
    private long solve(long[] v, long[] buf, int l, int r) {
        if (r - l <= 1) return 0;
        int m = (l + r) / 2;
        long cnt = solve(v, buf, l, m) + solve(v, buf, m, r);
        int i = l, j = m, k = l;
        while (i < m && j < r) {
            if (v[i] <= v[j]) { cnt += r - j; buf[k++] = v[i++]; }
            else buf[k++] = v[j++];
        }
        while (i < m) buf[k++] = v[i++];
        while (j < r) buf[k++] = v[j++];
        System.arraycopy(buf, l, v, l, r - l);
        return cnt;
    }
    public int countSubarrays(int[] nums, int a, int b) {
        long[] f = new long[nums.length + 1];
        long e = 0, o = 0;
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] % 2 == 0) e++; else o++;
            f[i + 1] = b * e - a * o;
        }
        return (int) solve(f, new long[f.length], 0, f.length);
    }
}

