var countSubarrays = function(nums, a, b) {
    const f = [0];
    let e = 0, o = 0;
    for (const x of nums) {
        if (x % 2 === 0) e++; else o++;
        f.push(b * e - a * o);
    }
    function solve(v) {
        if (v.length <= 1) return [v, 0];
        const m = v.length >> 1;
        const [lo, c1] = solve(v.slice(0, m));
        const [hi, c2] = solve(v.slice(m));
        let cnt = c1 + c2, res = [], i = 0, j = 0;
        while (i < lo.length && j < hi.length) {
            if (lo[i] <= hi[j]) { cnt += hi.length - j; res.push(lo[i++]); }
            else res.push(hi[j++]);
        }
        while (i < lo.length) res.push(lo[i++]);
        while (j < hi.length) res.push(hi[j++]);
        return [res, cnt];
    }
    return solve(f)[1];
};
